-- Bảng: pricing_plans
DROP TABLE IF EXISTS "pricing_plans" CASCADE;
CREATE TABLE "pricing_plans" (
    "id" bigint NOT NULL DEFAULT nextval('pricing_plans_id_seq'::regclass),
    "name" character varying NOT NULL,
    "description" text,
    "price" numeric NOT NULL,
    "billing_cycle" character varying NOT NULL,
    "credits_included" integer NOT NULL,
    "features" boolean NOT NULL DEFAULT false,
    "max_voice_clone" integer NOT NULL,
    "is_premium" boolean NOT NULL DEFAULT false,
    "is_active" boolean NOT NULL DEFAULT true,
    "sort_order" integer NOT NULL,
    "created_at" timestamp without time zone,
    "updated_at" timestamp without time zone,
    "credits" integer,
    "status" character varying NOT NULL DEFAULT 'active'::character varying,
    "is_popular" boolean NOT NULL DEFAULT false,
    "currency" character varying NOT NULL DEFAULT 'VND'::character varying
);

