-- Bảng: files
DROP TABLE IF EXISTS "files" CASCADE;
CREATE TABLE "files" (
    "id" bigint NOT NULL DEFAULT nextval('files_id_seq'::regclass),
    "user_id" bigint NOT NULL,
    "original_name" character varying NOT NULL,
    "stored_name" character varying NOT NULL,
    "file_path" character varying NOT NULL,
    "mime_type" character varying NOT NULL,
    "file_size" bigint NOT NULL,
    "file_extension" character varying NOT NULL,
    "file_type" character varying NOT NULL,
    "is_public" boolean NOT NULL DEFAULT false,
    "download_count" integer NOT NULL,
    "metadata" json,
    "hash" character varying,
    "last_accessed_at" timestamp without time zone,
    "created_at" timestamp without time zone,
    "updated_at" timestamp without time zone
);

-- Bảng: openai
DROP TABLE IF EXISTS "openai" CASCADE;
CREATE TABLE "openai" (
    "id" bigint NOT NULL DEFAULT nextval('openai_id_seq'::regclass),
    "user_id" bigint,
    "title" character varying NOT NULL,
    "description" text NOT NULL,
    "slug" character varying,
    "active" boolean NOT NULL DEFAULT true,
    "questions" text,
    "image" text,
    "premium" boolean NOT NULL DEFAULT false,
    "type" character varying NOT NULL DEFAULT 'text'::character varying,
    "prompt" text,
    "custom_template" boolean NOT NULL DEFAULT false,
    "tone_of_voice" boolean NOT NULL DEFAULT false,
    "color" character varying,
    "filters" text,
    "package" text,
    "created_at" timestamp without time zone,
    "updated_at" timestamp without time zone
);

INSERT INTO "openai" ("id", "user_id", "title", "description", "slug", "active", "questions", "image", "premium", "type", "prompt", "custom_template", "tone_of_voice", "color", "filters", "package", "created_at", "updated_at") VALUES
('1', NULL, 'Post Title Generator', 'Get captivating post titles instantly with our title generator. Boost engagement and save time.', 'post_title_generator', '1', '"[{\"name\":\"your_description\",\"type\":\"textarea\",\"question\":\"Description\",\"select\":\"\"}]"', '<svg xmlns="http://www.w3.org/2000/svg" height="48" viewBox="0 96 960 960" width="48"><path d="M430 896V356H200V256h560v100H530v540H430Z"/></svg>', '', 'text', NULL, '', '', '#A3D6C2', '"blog"', NULL, '2025-09-26 14:23:05', '2025-09-26 14:23:05'),
('2', NULL, 'Summarize Text', 'Effortlessly condense large text into shorter summaries. Save time and increase productivity.', 'summarize_text', '1', '"[{\"name\":\"text_to_summary\",\"type\":\"textarea\",\"question\":\"Text to summary\",\"select\":\"\"}]"', '<svg xmlns="http://www.w3.org/2000/svg" height="48" viewBox="0 96 960 960" width="48"><path d="M120 816v-60h480v60H120Zm0-210v-60h720v60H120Zm0-210v-60h720v60H120Z"/></svg>', '', 'text', NULL, '', '', '#CCD9B8', '"blog"', NULL, '2025-09-26 14:23:06', '2025-09-26 14:23:06'),
('3', NULL, 'Product Description', 'Easily create compelling product descriptions that sell. Increase conversions and boost sales.', 'product_description', '1', '"[{\"name\":\"product_name\",\"type\":\"text\",\"question\":\"Product Name\",\"select\":\"\"},{\"name\":\"description\",\"type\":\"textarea\",\"question\":\"Short Description\",\"select\":\"\"}]"', '<svg xmlns="http://www.w3.org/2000/svg" height="48" viewBox="0 96 960 960" width="48"><path d="M319 806h322v-60H319v60Zm0-170h322v-60H319v60Zm-99 340q-24 0-42-18t-18-42V236q0-24 18-42t42-18h361l219 219v521q0 24-18 42t-42 18H220Zm331-554h189L551 236v186Z"/></svg>', '', 'text', NULL, '', '', '#C2DEDD', '"ecommerce"', NULL, '2025-09-26 14:23:06', '2025-09-26 14:23:06'),
('4', NULL, 'Article Generator', 'Instantly create unique articles on any topic. Boost engagement, improve SEO, and save time.', 'article_generator', '1', '"[{\"name\":\"article_title\",\"type\":\"text\",\"question\":\"Article Title\",\"select\":\"\"},{\"name\":\"focus_keywords\",\"type\":\"text\",\"question\":\"Focus Keywords (Seperate with Comma)\",\"select\":\"\"}]"', '<svg xmlns="http://www.w3.org/2000/svg" height="48" viewBox="0 96 960 960" width="48"><path d="M140 936q-24.75 0-42.375-17.625T80 876V216l67 67 66-67 67 67 67-67 66 67 67-67 67 67 66-67 67 67 67-67 66 67 67-67v660q0 24.75-17.625 42.375T820 936H140Zm0-60h310V596H140v280Zm370 0h310V766H510v110Zm0-170h310V596H510v110ZM140 536h680V416H140v120Z"/></svg>', '', 'text', NULL, '', '', '#A3D6C2', '"blog"', NULL, '2025-09-26 14:23:06', '2025-09-26 14:23:06'),
('5', NULL, 'Product Name Generator', 'Create catchy product names with ease. Attract customers and boost sales effortlessly.', 'product_name', '1', '"[{\"name\":\"seed_words\",\"type\":\"text\",\"question\":\"Seed Words (Seperate With Comma)\",\"select\":\"\"},{\"name\":\"product_description\",\"type\":\"textarea\",\"question\":\"Product Description\",\"select\":\"\"}]"', '<svg xmlns="http://www.w3.org/2000/svg" height="48" viewBox="0 96 960 960" width="48"><path d="M290 896V356H80V256h520v100H390v540H290Zm360 0V556H520V456h360v100H750v340H650Z"/></svg>', '', 'text', NULL, '', '', '#C2DEDD', '"ecommerce"', NULL, '2025-09-26 14:23:07', '2025-09-26 14:23:07'),
